  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

-- ============================================================
-- 20261023000300_retention.sql
-- ============================================================
-- Data retention (Act 843 "no longer than necessary"). Draft windows from Phase 0 doc 2.1,
-- to be confirmed with a lawyer (ADR 0012):
--   fare, overcharge and hazard reports: kept, but anonymised after 90 days
--   trip summaries: 12 months
--   expired weather cache: 7 days
-- Raw GPS points (Phase 2 location_pings, 30 days) are added to this function in Phase 2.

create or replace function public.purge_expired_data()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  result jsonb := '{}'::jsonb;
  n integer;
begin
  update public.fare_reports set user_id = null
  where user_id is not null and created_at < now() - interval '90 days';
  get diagnostics n = row_count;
  result := result || jsonb_build_object('fare_reports_anonymised', n);

  update public.overcharge_reports set user_id = null, vehicle_plate = null
  where user_id is not null and created_at < now() - interval '90 days';
  get diagnostics n = row_count;
  result := result || jsonb_build_object('overcharge_reports_anonymised', n);

  update public.hazard_reports set user_id = null
  where user_id is not null and created_at < now() - interval '90 days';
  get diagnostics n = row_count;
  result := result || jsonb_build_object('hazard_reports_anonymised', n);

  delete from public.trips_planned where created_at < now() - interval '12 months';
  get diagnostics n = row_count;
  result := result || jsonb_build_object('trips_planned_deleted', n);

  delete from public.weather_snapshots where forecast_for < now() - interval '7 days';
  get diagnostics n = row_count;
  result := result || jsonb_build_object('weather_snapshots_deleted', n);

  return result;
end;
$$;

revoke execute on function public.purge_expired_data() from public, anon, authenticated;

-- Supabase ships pg_cron; plain Postgres (CI) may not, so schedule only when it is available.
do $$
begin
  if exists (select 1 from pg_available_extensions where name = 'pg_cron') then
    create extension if not exists pg_cron;
    perform cron.schedule('purge-expired-data', '17 2 * * *', 'select public.purge_expired_data()');
  end if;
end;
$$;

-- ============================================================
-- 20261024000100_admin_tools.sql
-- ============================================================
-- Admin tools for the field team (P1-ADMIN): station editor with plain coordinates,
-- report moderation through one audited function.

-- ---------------------------------------------------------------------------
-- Stations: readable coordinates, and a save function that takes latitude/longitude
-- ---------------------------------------------------------------------------

alter table public.stations
  add column latitude double precision
    generated always as (extensions.st_y(location::extensions.geometry)) stored,
  add column longitude double precision
    generated always as (extensions.st_x(location::extensions.geometry)) stored;

-- Creates a station (p_id null) or updates one. Runs with the caller's rights,
-- so row level security decides who may save.
create or replace function public.save_station(
  p_id uuid,
  p_name text,
  p_slug text,
  p_kind text,
  p_city text,
  p_region text,
  p_latitude double precision,
  p_longitude double precision,
  p_ghanapost_gps text default null,
  p_is_active boolean default true
)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  saved_id uuid;
  point extensions.geography;
begin
  -- Ghana lies roughly within 4.5-11.5 N and 3.5 W-1.5 E; reject swapped or mistyped coordinates.
  if p_latitude not between 4.5 and 11.5 or p_longitude not between -3.5 and 1.5 then
    raise exception 'coordinates % , % are outside Ghana', p_latitude, p_longitude using errcode = '22023';
  end if;
  point := extensions.st_setsrid(extensions.st_makepoint(p_longitude, p_latitude), 4326)::extensions.geography;

  if p_id is null then
    insert into public.stations (name, slug, kind, city, region, location, ghanapost_gps, is_active)
    values (p_name, p_slug, p_kind, p_city, p_region, point, nullif(p_ghanapost_gps, ''), p_is_active)
    returning id into saved_id;
  else
    update public.stations
       set name = p_name, slug = p_slug, kind = p_kind, city = p_city, region = p_region,
           location = point, ghanapost_gps = nullif(p_ghanapost_gps, ''), is_active = p_is_active
     where id = p_id
    returning id into saved_id;
    if saved_id is null then
      raise exception 'station % not found or not editable', p_id using errcode = 'P0002';
    end if;
  end if;
  return saved_id;
end;
$$;

revoke execute on function public.save_station(uuid, text, text, text, text, text, double precision, double precision, text, boolean) from public, anon;
grant execute on function public.save_station(uuid, text, text, text, text, text, double precision, double precision, text, boolean) to authenticated;

-- ---------------------------------------------------------------------------
-- Moderation: moderators change only the status, never the reported amounts
-- ---------------------------------------------------------------------------

drop policy "fare_reports: moderators update" on public.fare_reports;
drop policy "overcharge_reports: moderators update" on public.overcharge_reports;
drop policy "hazard_reports: moderators update" on public.hazard_reports;

create or replace function public.moderate_report(p_kind text, p_id uuid, p_status text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  target text;
  updated integer;
begin
  if not public.can_moderate() then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if p_status not in ('accepted', 'rejected') then
    raise exception 'status must be accepted or rejected' using errcode = '22023';
  end if;
  target := case p_kind
    when 'fare' then 'fare_reports'
    when 'overcharge' then 'overcharge_reports'
    when 'hazard' then 'hazard_reports'
  end;
  if target is null then
    raise exception 'unknown report kind %', p_kind using errcode = '22023';
  end if;

  execute format('update public.%I set status = $1, moderated_by = $2 where id = $3', target)
    using p_status, auth.uid(), p_id;
  -- EXECUTE does not set FOUND; read the row count instead.
  get diagnostics updated = row_count;
  if updated = 0 then
    raise exception 'report % not found', p_id using errcode = 'P0002';
  end if;
end;
$$;

revoke execute on function public.moderate_report(text, uuid, text) from public, anon;
grant execute on function public.moderate_report(text, uuid, text) to authenticated;

-- Reports are not copied into audit_log (it would keep reporter ids past the 90-day
-- anonymisation); moderated_by records who decided.

-- Staff edits to these tables were not audited in the first migration.
create trigger fare_sources_audit after insert or update or delete on public.fare_sources
  for each row execute function public.audit_row();
create trigger route_stops_audit after insert or update or delete on public.route_stops
  for each row execute function public.audit_row();
create trigger places_audit after insert or update or delete on public.places
  for each row execute function public.audit_row();

-- ============================================================
-- 20261024000200_feature_flag_rollout_default.sql
-- ============================================================
-- A switch that is turned on should reach everyone unless a rollout percentage is set,
-- so the default rollout becomes 100% (the app treats 0% as nobody).
alter table public.feature_flags alter column rollout_percent set default 100;
comment on column public.feature_flags.rollout_percent is
  'Share of devices (by stable bucket 0-99) that get the feature when enabled. 100 = everyone.';

-- ============================================================
-- 20261024000300_spreadsheet_import.sql
-- ============================================================
-- Spreadsheet import for the field team (Phase 0 doc 4.2). The admin checks every row in the
-- browser first; these functions apply the checked rows one by one, so a bad row is reported
-- with its spreadsheet line and the rest still go in. Both run with the caller's rights.

alter table public.fares
  add column collected_by text,
  add column evidence_url text;
comment on column public.fares.collected_by is 'Field researcher who recorded this fare.';
comment on column public.fares.evidence_url is 'Photo of the station board or price list.';

-- rows: [{line, name, slug, kind, city, region, latitude, longitude, ghanapost_gps}]
create or replace function public.import_stations(rows jsonb)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
  r jsonb;
  existing uuid;
  results jsonb := '[]'::jsonb;
begin
  if not public.can_edit_reference_data() then
    raise exception 'not allowed' using errcode = '42501';
  end if;

  for r in select * from jsonb_array_elements(rows) loop
    begin
      select id into existing from public.stations where slug = r ->> 'slug';
      perform public.save_station(
        existing, r ->> 'name', r ->> 'slug', r ->> 'kind', r ->> 'city', r ->> 'region',
        (r ->> 'latitude')::double precision, (r ->> 'longitude')::double precision,
        r ->> 'ghanapost_gps', true
      );
      results := results || jsonb_build_object(
        'line', r -> 'line', 'status', case when existing is null then 'created' else 'updated' end);
    exception when others then
      results := results || jsonb_build_object('line', r -> 'line', 'status', 'error', 'message', sqlerrm);
    end;
  end loop;
  return results;
end;
$$;

-- rows: [{line, origin_station_id, destination_station_id, route_kind, operator_id, vehicle_type,
--         class, amount_pesewas, is_official, observed_on, source_name, source_kind,
--         departure_mode, first_departure, last_departure, collected_by, evidence_url}]
-- Per row: no current fare -> created; same amount -> confirmed; new amount observed on or after
-- the current fare's last confirmation -> changed (history kept); older observation -> skipped.
create or replace function public.import_fares(rows jsonb)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
  r jsonb;
  v_route_id uuid;
  v_source_id uuid;
  current_fare public.fares;
  observed_at timestamptz;
  new_id uuid;
  results jsonb := '[]'::jsonb;
begin
  if not public.can_edit_reference_data() then
    raise exception 'not allowed' using errcode = '42501';
  end if;

  for r in select * from jsonb_array_elements(rows) loop
    begin
      -- Field observations count as noon Accra time on the day observed.
      observed_at := ((r ->> 'observed_on')::date + time '12:00') at time zone 'Africa/Accra';

      select id into v_route_id from public.routes
      where origin_station_id = (r ->> 'origin_station_id')::uuid
        and destination_station_id = (r ->> 'destination_station_id')::uuid
        and kind = r ->> 'route_kind';
      if v_route_id is null then
        insert into public.routes (origin_station_id, destination_station_id, kind)
        values ((r ->> 'origin_station_id')::uuid, (r ->> 'destination_station_id')::uuid, r ->> 'route_kind')
        returning id into v_route_id;
      end if;

      v_source_id := null;
      if coalesce(r ->> 'source_name', '') <> '' then
        select id into v_source_id from public.fare_sources where lower(name) = lower(r ->> 'source_name') limit 1;
        if v_source_id is null then
          insert into public.fare_sources (kind, name, document_date)
          values ((r ->> 'source_kind')::public.fare_source_kind, r ->> 'source_name', (r ->> 'observed_on')::date)
          returning id into v_source_id;
        end if;
      end if;

      select * into current_fare from public.fares f
      where f.route_id = v_route_id
        and f.operator_id is not distinct from (r ->> 'operator_id')::uuid
        and f.vehicle_type = r ->> 'vehicle_type'
        and f.class = r ->> 'class'
        and f.effective_to is null;

      if current_fare.id is null then
        insert into public.fares (
          route_id, operator_id, vehicle_type, class, amount_pesewas, is_official, source_id,
          effective_from, last_confirmed_at, departure_mode, first_departure, last_departure,
          collected_by, evidence_url
        ) values (
          v_route_id, (r ->> 'operator_id')::uuid, r ->> 'vehicle_type', r ->> 'class',
          (r ->> 'amount_pesewas')::integer, (r ->> 'is_official')::boolean, v_source_id,
          (r ->> 'observed_on')::date, observed_at, r ->> 'departure_mode',
          (r ->> 'first_departure')::time, (r ->> 'last_departure')::time,
          r ->> 'collected_by', r ->> 'evidence_url'
        );
        results := results || jsonb_build_object('line', r -> 'line', 'status', 'created');

      elsif current_fare.amount_pesewas = (r ->> 'amount_pesewas')::integer then
        update public.fares
           set last_confirmed_at = greatest(last_confirmed_at, observed_at),
               collected_by = coalesce(r ->> 'collected_by', collected_by),
               evidence_url = coalesce(r ->> 'evidence_url', evidence_url)
         where id = current_fare.id;
        results := results || jsonb_build_object('line', r -> 'line', 'status', 'confirmed');

      elsif observed_at::date < (current_fare.last_confirmed_at at time zone 'Africa/Accra')::date then
        results := results || jsonb_build_object(
          'line', r -> 'line', 'status', 'skipped',
          'message', format('the current fare of %s pesewas was confirmed more recently, on %s',
                            current_fare.amount_pesewas,
                            to_char(current_fare.last_confirmed_at at time zone 'Africa/Accra', 'DD/MM/YYYY')));

      else
        new_id := public.change_fare(
          current_fare.id, (r ->> 'amount_pesewas')::integer,
          coalesce(v_source_id, current_fare.source_id), greatest((r ->> 'observed_on')::date, current_fare.effective_from)
        );
        update public.fares
           set last_confirmed_at = observed_at,
               is_official = (r ->> 'is_official')::boolean,
               departure_mode = r ->> 'departure_mode',
               first_departure = coalesce((r ->> 'first_departure')::time, first_departure),
               last_departure = coalesce((r ->> 'last_departure')::time, last_departure),
               collected_by = r ->> 'collected_by',
               evidence_url = r ->> 'evidence_url'
         where id = new_id;
        results := results || jsonb_build_object('line', r -> 'line', 'status', 'changed',
          'message', format('was %s pesewas', current_fare.amount_pesewas));
      end if;
    exception when others then
      results := results || jsonb_build_object('line', r -> 'line', 'status', 'error', 'message', sqlerrm);
    end;
  end loop;
  return results;
end;
$$;

revoke execute on function public.import_stations(jsonb) from public, anon;
revoke execute on function public.import_fares(jsonb) from public, anon;
grant execute on function public.import_stations(jsonb) to authenticated;
grant execute on function public.import_fares(jsonb) to authenticated;

-- ============================================================
-- 20261024000400_consent_required.sql
-- ============================================================
-- Reports are only accepted from users whose latest answer to both the terms and the privacy
-- notice is "yes" (Act 843 / Act 772). The app asks again when the document version changes.

create or replace function public.has_agreed_terms()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(count(*) = 2 and bool_and(granted), false)
  from (
    select distinct on (consent_type) consent_type, granted
    from public.consents
    where user_id = (select auth.uid()) and consent_type in ('terms', 'privacy')
    order by consent_type, created_at desc
  ) latest;
$$;

drop policy "fare_reports: add own" on public.fare_reports;
create policy "fare_reports: add own" on public.fare_reports for insert to authenticated
  with check (user_id = (select auth.uid()) and status = 'pending' and public.has_agreed_terms());

drop policy "overcharge_reports: add own" on public.overcharge_reports;
create policy "overcharge_reports: add own" on public.overcharge_reports for insert to authenticated
  with check (user_id = (select auth.uid()) and status = 'pending' and public.has_agreed_terms());

drop policy "hazard_reports: add own" on public.hazard_reports;
create policy "hazard_reports: add own" on public.hazard_reports for insert to authenticated
  with check (user_id = (select auth.uid()) and status = 'pending' and public.has_agreed_terms());

-- ============================================================
-- 20261024000500_saved_route_alerts.sql
-- ============================================================
-- Saved routes and fare-change alerts (P1-NOTIF): when a current fare is replaced by a new
-- price (admin change, spreadsheet import), everyone who saved that route with alerts on gets
-- an in-app notification. Push delivery is added once the push vendor is set up.

create or replace function public.notify_fare_change()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  previous public.fares;
begin
  -- change_fare() closes the old row on the day the new one starts.
  select * into previous from public.fares f
  where f.route_id = new.route_id
    and f.operator_id is not distinct from new.operator_id
    and f.vehicle_type = new.vehicle_type
    and f.class = new.class
    and f.id <> new.id
    and f.effective_to = new.effective_from
  order by f.created_at desc
  limit 1;

  if previous.id is null or previous.amount_pesewas = new.amount_pesewas then
    return null;
  end if;

  insert into public.notifications (user_id, kind, payload)
  select s.user_id, 'fare_changed', jsonb_build_object(
    'route_id', r.id,
    'origin_id', r.origin_station_id,
    'destination_id', r.destination_station_id,
    'origin_name', o.name,
    'destination_name', d.name,
    'fare_id', new.id,
    'operator_name', op.name,
    'vehicle_type', new.vehicle_type,
    'vehicle_type_name', vt.name,
    'class', new.class,
    'old_pesewas', previous.amount_pesewas,
    'new_pesewas', new.amount_pesewas,
    'effective_from', new.effective_from
  )
  from public.saved_routes s
  join public.routes r on r.id = s.route_id
  join public.stations o on o.id = r.origin_station_id
  join public.stations d on d.id = r.destination_station_id
  join public.vehicle_types vt on vt.code = new.vehicle_type
  left join public.operators op on op.id = new.operator_id
  where s.route_id = new.route_id and s.notify_fare_changes;

  return null;
end;
$$;

create trigger fares_notify_change after insert on public.fares
  for each row execute function public.notify_fare_change();

create index saved_routes_route_idx on public.saved_routes (route_id) where notify_fare_changes;
create index notifications_unread_idx on public.notifications (user_id) where read_at is null;

-- "Download my data" now includes alerts.
create or replace function public.export_my_data()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'exported_at', now(),
    'profile', (select to_jsonb(p) from public.profiles p where p.id = auth.uid()),
    'consents', coalesce((select jsonb_agg(c order by c.created_at) from public.consents c where c.user_id = auth.uid()), '[]'),
    'devices', coalesce((select jsonb_agg(d) from public.devices d where d.user_id = auth.uid()), '[]'),
    'saved_routes', coalesce((select jsonb_agg(s) from public.saved_routes s where s.user_id = auth.uid()), '[]'),
    'trips_planned', coalesce((select jsonb_agg(t) from public.trips_planned t where t.user_id = auth.uid()), '[]'),
    'fare_reports', coalesce((select jsonb_agg(f) from public.fare_reports f where f.user_id = auth.uid()), '[]'),
    'overcharge_reports', coalesce((select jsonb_agg(o) from public.overcharge_reports o where o.user_id = auth.uid()), '[]'),
    'hazard_reports', coalesce((select jsonb_agg(h) from public.hazard_reports h where h.user_id = auth.uid()), '[]'),
    'notifications', coalesce((select jsonb_agg(n order by n.created_at) from public.notifications n where n.user_id = auth.uid()), '[]')
  );
$$;

-- Alerts are kept 90 days.
create or replace function public.purge_expired_data()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  result jsonb := '{}'::jsonb;
  n integer;
begin
  update public.fare_reports set user_id = null
  where user_id is not null and created_at < now() - interval '90 days';
  get diagnostics n = row_count;
  result := result || jsonb_build_object('fare_reports_anonymised', n);

  update public.overcharge_reports set user_id = null, vehicle_plate = null
  where user_id is not null and created_at < now() - interval '90 days';
  get diagnostics n = row_count;
  result := result || jsonb_build_object('overcharge_reports_anonymised', n);

  update public.hazard_reports set user_id = null
  where user_id is not null and created_at < now() - interval '90 days';
  get diagnostics n = row_count;
  result := result || jsonb_build_object('hazard_reports_anonymised', n);

  delete from public.trips_planned where created_at < now() - interval '12 months';
  get diagnostics n = row_count;
  result := result || jsonb_build_object('trips_planned_deleted', n);

  delete from public.weather_snapshots where forecast_for < now() - interval '7 days';
  get diagnostics n = row_count;
  result := result || jsonb_build_object('weather_snapshots_deleted', n);

  delete from public.notifications where created_at < now() - interval '90 days';
  get diagnostics n = row_count;
  result := result || jsonb_build_object('notifications_deleted', n);

  return result;
end;
$$;

-- ============================================================
-- 20261027000100_flood_prone_stations.sql
-- ============================================================
-- P1-WX-02: stations the field team marks as flood-prone get a stronger warning when heavy
-- rain is forecast there. save_station gains p_flood_prone (default false keeps old calls working).

alter table public.stations add column flood_prone boolean not null default false;
comment on column public.stations.flood_prone is 'Floods in heavy rain (e.g. Kwame Nkrumah Circle / Odaw). Set by the field team.';

drop function public.save_station(uuid, text, text, text, text, text, double precision, double precision, text, boolean);

-- Creates a station (p_id null) or updates one. Runs with the caller's rights,
-- so row level security decides who may save.
create function public.save_station(
  p_id uuid,
  p_name text,
  p_slug text,
  p_kind text,
  p_city text,
  p_region text,
  p_latitude double precision,
  p_longitude double precision,
  p_ghanapost_gps text default null,
  p_is_active boolean default true,
  p_flood_prone boolean default false
)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  saved_id uuid;
  point extensions.geography;
begin
  -- Ghana lies roughly within 4.5-11.5 N and 3.5 W-1.5 E; reject swapped or mistyped coordinates.
  if p_latitude not between 4.5 and 11.5 or p_longitude not between -3.5 and 1.5 then
    raise exception 'coordinates % , % are outside Ghana', p_latitude, p_longitude using errcode = '22023';
  end if;
  point := extensions.st_setsrid(extensions.st_makepoint(p_longitude, p_latitude), 4326)::extensions.geography;

  if p_id is null then
    insert into public.stations (name, slug, kind, city, region, location, ghanapost_gps, is_active, flood_prone)
    values (p_name, p_slug, p_kind, p_city, p_region, point, nullif(p_ghanapost_gps, ''), p_is_active, p_flood_prone)
    returning id into saved_id;
  else
    update public.stations
       set name = p_name, slug = p_slug, kind = p_kind, city = p_city, region = p_region,
           location = point, ghanapost_gps = nullif(p_ghanapost_gps, ''), is_active = p_is_active,
           flood_prone = p_flood_prone
     where id = p_id
    returning id into saved_id;
    if saved_id is null then
      raise exception 'station % not found or not editable', p_id using errcode = 'P0002';
    end if;
  end if;
  return saved_id;
end;
$$;

revoke execute on function public.save_station(uuid, text, text, text, text, text, double precision, double precision, text, boolean, boolean) from public, anon;
grant execute on function public.save_station(uuid, text, text, text, text, text, double precision, double precision, text, boolean, boolean) to authenticated;

-- ============================================================
-- 20261028000100_safety.sql
-- ============================================================
-- Safety (P1-SAFE): emergency numbers, reports about a driver (reckless driving, abuse of
-- passengers) with photos of the vehicle, and passenger ratings of the driver.

-- ---------------------------------------------------------------------------
-- Emergency numbers: shown in the app (and saved on the phone), edited by staff
-- ---------------------------------------------------------------------------

create table public.emergency_contacts (
  id uuid primary key default gen_random_uuid(),
  name text not null check (char_length(name) between 2 and 80),
  phone text not null check (phone ~ '^\+?[0-9]{3,15}$'),
  kind text not null check (kind in ('emergency', 'police', 'fire', 'ambulance', 'road_safety', 'operator', 'other')),
  note text check (char_length(note) <= 200),
  sort_order integer not null default 100,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create trigger emergency_contacts_set_updated_at before update on public.emergency_contacts
  for each row execute function public.set_updated_at();
create trigger emergency_contacts_audit after insert or update or delete on public.emergency_contacts
  for each row execute function public.audit_row();

alter table public.emergency_contacts enable row level security;
create policy "emergency_contacts: public read" on public.emergency_contacts for select to anon, authenticated
  using (is_active or public.can_edit_reference_data());
create policy "emergency_contacts: staff write" on public.emergency_contacts for all to authenticated
  using (public.can_edit_reference_data()) with check (public.can_edit_reference_data());

-- 112 is the national number for police, fire and ambulance (2020). The older direct numbers
-- are still widely listed. Staff add MTTD, NRSA and operator lines once confirmed.
insert into public.emergency_contacts (name, phone, kind, note, sort_order) values
  ('All emergencies', '112', 'emergency', 'Police, fire and ambulance', 10),
  ('Police', '191', 'police', null, 20),
  ('Police (toll-free)', '18555', 'police', null, 30),
  ('Fire service', '192', 'fire', null, 40),
  ('Ambulance', '193', 'ambulance', null, 50);

-- ---------------------------------------------------------------------------
-- Reports about a driver, with up to 3 photos of the vehicle
-- ---------------------------------------------------------------------------

create table public.driver_reports (
  id uuid primary key default gen_random_uuid(),
  client_id uuid not null unique,
  user_id uuid default auth.uid() references auth.users (id) on delete set null,
  kind text not null check (kind in (
    'reckless_driving', 'drunk_driving', 'abuse', 'harassment', 'overloading', 'unroadworthy', 'other'
  )),
  vehicle_plate text check (char_length(vehicle_plate) <= 15),
  route_id uuid references public.routes (id),
  operator_id uuid references public.operators (id),
  occurred_at timestamptz not null,
  location extensions.geography(Point, 4326),
  note text check (char_length(note) <= 1000),
  -- Storage paths in the report-photos bucket, each under the reporter's own folder.
  photo_paths text[] not null default '{}' check (cardinality(photo_paths) <= 3),
  status text not null default 'pending' check (status in ('pending', 'forwarded', 'closed', 'rejected')),
  forwarded_to text check (char_length(forwarded_to) <= 120),
  staff_note text check (char_length(staff_note) <= 1000),
  moderated_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now()
);
comment on column public.driver_reports.forwarded_to is 'Who staff sent it to, e.g. "MTTD Accra", "NRSA", "VIP Jeoun".';
create index driver_reports_status_idx on public.driver_reports (status, created_at desc);
create index driver_reports_user_idx on public.driver_reports (user_id, created_at desc);

create trigger driver_reports_rate_limit before insert on public.driver_reports
  for each row execute function public.enforce_report_rate_limit();

alter table public.driver_reports enable row level security;
create policy "driver_reports: add own" on public.driver_reports for insert to authenticated
  with check (
    user_id = (select auth.uid()) and status = 'pending' and forwarded_to is null and staff_note is null
    and public.has_agreed_terms()
    and not exists (select 1 from unnest(photo_paths) p where split_part(p, '/', 1) <> (select auth.uid())::text)
  );
create policy "driver_reports: read own or moderate" on public.driver_reports for select to authenticated
  using (user_id = (select auth.uid()) or public.can_moderate());

-- Staff record what they did with a report; nothing else about it can change.
create or replace function public.handle_driver_report(p_id uuid, p_status text, p_forwarded_to text, p_staff_note text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not public.can_moderate() then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if p_status not in ('forwarded', 'closed', 'rejected') then
    raise exception 'status must be forwarded, closed or rejected' using errcode = '22023';
  end if;
  if p_status = 'forwarded' and coalesce(btrim(p_forwarded_to), '') = '' then
    raise exception 'say who it was forwarded to' using errcode = '22023';
  end if;
  update public.driver_reports
     set status = p_status,
         forwarded_to = coalesce(nullif(btrim(p_forwarded_to), ''), forwarded_to),
         staff_note = nullif(btrim(p_staff_note), ''),
         moderated_by = auth.uid()
   where id = p_id;
  if not found then
    raise exception 'report % not found', p_id using errcode = 'P0002';
  end if;
end;
$$;

revoke execute on function public.handle_driver_report(uuid, text, text, text) from public, anon;
grant execute on function public.handle_driver_report(uuid, text, text, text) to authenticated;

-- ---------------------------------------------------------------------------
-- Passenger ratings of the driver
-- ---------------------------------------------------------------------------

create table public.driver_ratings (
  id uuid primary key default gen_random_uuid(),
  client_id uuid not null unique,
  user_id uuid default auth.uid() references auth.users (id) on delete set null,
  rating smallint not null check (rating between 1 and 5),
  tags text[] not null default '{}' check (tags <@ array[
    'safe_driving', 'polite', 'clean_vehicle', 'on_time', 'fair_fare',
    'reckless', 'rude', 'dirty_vehicle', 'overloaded', 'overcharged'
  ]::text[]),
  vehicle_plate text check (char_length(vehicle_plate) <= 15),
  route_id uuid references public.routes (id),
  operator_id uuid references public.operators (id),
  comment text check (char_length(comment) <= 500),
  travelled_at timestamptz not null,
  created_at timestamptz not null default now()
);
create index driver_ratings_operator_idx on public.driver_ratings (operator_id, created_at desc);

create trigger driver_ratings_rate_limit before insert on public.driver_ratings
  for each row execute function public.enforce_report_rate_limit();

alter table public.driver_ratings enable row level security;
create policy "driver_ratings: add own" on public.driver_ratings for insert to authenticated
  with check (user_id = (select auth.uid()) and public.has_agreed_terms());
create policy "driver_ratings: read own or moderate" on public.driver_ratings for select to authenticated
  using (user_id = (select auth.uid()) or public.can_moderate());

-- ---------------------------------------------------------------------------
-- Photo storage: private bucket; people upload into their own folder, staff read and delete
-- ---------------------------------------------------------------------------

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('report-photos', 'report-photos', false, 5242880, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do nothing;

create policy "report-photos: upload own" on storage.objects for insert to authenticated
  with check (bucket_id = 'report-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy "report-photos: read own or moderate" on storage.objects for select to authenticated
  using (bucket_id = 'report-photos' and ((storage.foldername(name))[1] = (select auth.uid())::text or public.can_moderate()));
create policy "report-photos: moderators delete" on storage.objects for delete to authenticated
  using (bucket_id = 'report-photos' and public.can_moderate());

-- Photos of reports older than 90 days, for staff to delete through the Storage API
-- (deleting storage rows in SQL would leave the files behind).
create or replace function public.expired_report_photos()
returns table (report_id uuid, photo_paths text[])
language sql
stable
security definer
set search_path = ''
as $$
  select id, photo_paths from public.driver_reports
  where public.can_moderate() and cardinality(photo_paths) > 0 and created_at < now() - interval '90 days';
$$;

create or replace function public.forget_report_photos(p_ids uuid[])
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  n integer;
begin
  if not public.can_moderate() then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  update public.driver_reports set photo_paths = '{}'
  where id = any (p_ids) and created_at < now() - interval '90 days';
  get diagnostics n = row_count;
  return n;
end;
$$;

revoke execute on function public.expired_report_photos(), public.forget_report_photos(uuid[]) from public, anon;
grant execute on function public.expired_report_photos(), public.forget_report_photos(uuid[]) to authenticated;

-- ---------------------------------------------------------------------------
-- Privacy: export and retention cover the new tables
-- ---------------------------------------------------------------------------

create or replace function public.export_my_data()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'exported_at', now(),
    'profile', (select to_jsonb(p) from public.profiles p where p.id = auth.uid()),
    'consents', coalesce((select jsonb_agg(c order by c.created_at) from public.consents c where c.user_id = auth.uid()), '[]'),
    'devices', coalesce((select jsonb_agg(d) from public.devices d where d.user_id = auth.uid()), '[]'),
    'saved_routes', coalesce((select jsonb_agg(s) from public.saved_routes s where s.user_id = auth.uid()), '[]'),
    'trips_planned', coalesce((select jsonb_agg(t) from public.trips_planned t where t.user_id = auth.uid()), '[]'),
    'fare_reports', coalesce((select jsonb_agg(f) from public.fare_reports f where f.user_id = auth.uid()), '[]'),
    'overcharge_reports', coalesce((select jsonb_agg(o) from public.overcharge_reports o where o.user_id = auth.uid()), '[]'),
    'hazard_reports', coalesce((select jsonb_agg(h) from public.hazard_reports h where h.user_id = auth.uid()), '[]'),
    'notifications', coalesce((select jsonb_agg(n order by n.created_at) from public.notifications n where n.user_id = auth.uid()), '[]'),
    'driver_reports', coalesce((select jsonb_agg(r order by r.created_at) from public.driver_reports r where r.user_id = auth.uid()), '[]'),
    'driver_ratings', coalesce((select jsonb_agg(r order by r.created_at) from public.driver_ratings r where r.user_id = auth.uid()), '[]')
  );
$$;

-- Driver reports and ratings: anonymised after 90 days, like the other reports.
create or replace function public.purge_expired_data()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  result jsonb := '{}'::jsonb;
  n integer;
begin
  update public.fare_reports set user_id = null
  where user_id is not null and created_at < now() - interval '90 days';
  get diagnostics n = row_count;
  result := result || jsonb_build_object('fare_reports_anonymised', n);

  update public.overcharge_reports set user_id = null, vehicle_plate = null
  where user_id is not null and created_at < now() - interval '90 days';
  get diagnostics n = row_count;
  result := result || jsonb_build_object('overcharge_reports_anonymised', n);

  update public.hazard_reports set user_id = null
  where user_id is not null and created_at < now() - interval '90 days';
  get diagnostics n = row_count;
  result := result || jsonb_build_object('hazard_reports_anonymised', n);

  update public.driver_reports set user_id = null, vehicle_plate = null
  where (user_id is not null or vehicle_plate is not null) and created_at < now() - interval '90 days';
  get diagnostics n = row_count;
  result := result || jsonb_build_object('driver_reports_anonymised', n);

  update public.driver_ratings set user_id = null, vehicle_plate = null
  where (user_id is not null or vehicle_plate is not null) and created_at < now() - interval '90 days';
  get diagnostics n = row_count;
  result := result || jsonb_build_object('driver_ratings_anonymised', n);

  delete from public.trips_planned where created_at < now() - interval '12 months';
  get diagnostics n = row_count;
  result := result || jsonb_build_object('trips_planned_deleted', n);

  delete from public.weather_snapshots where forecast_for < now() - interval '7 days';
  get diagnostics n = row_count;
  result := result || jsonb_build_object('weather_snapshots_deleted', n);

  delete from public.notifications where created_at < now() - interval '90 days';
  get diagnostics n = row_count;
  result := result || jsonb_build_object('notifications_deleted', n);

  return result;
end;
$$;

